    "ದಕ್ಷಿಣ-ಪಶ್ಚಿಮ ದಿಕ್ಕಿನಲ್ಲಿ ಭಾರವಾದ ಫರ್ನಿಚರ್ ಮತ್ತು ಸಂಗ್ರಹಣೆಯನ್ನು ಇಡಿ.",
