                    "ಸ್ಟೌವ್ ಹಿಂದಿನ ಗೋಡೆಯಲ್ಲಿ ಕನ್ನಡಿ ಇಡಿ.",
                    "ಅಗ್ನಿ ತತ್ವದ ಬಣ್ಣಗಳು (ಕೆಂಪು, ಕಿತ್ತಳೆ) ಬಳಸಿ.",
                    "ದಕ್ಷಿಣ-ಪೂರ್ವ ಮೂಲೆಗಲ್ಲಿ ತಾಮ್ರ ಆಮೆಯನ್ನು ಇಡಿ.",
                    "ಕಪ್ಪು ಅಥವಾ ನೀಲಿ ಬಣ್ಣಗಳನ್ನು ತಪ್ಪಿಸಿ.",
