                    "ಅಗ್ನಿ ಪ್ರದೇಶದ ಬಳಿ ನೀರಿನ ಅಂಶಗಳನ್ನು ತಪ್ಪಿಸಿ.",
                    "ಫ್ರಿಜ್ ಅನ್ನು ಉತ್ತರ-ಪಶ್ಚಿಮ ದಿಕ್ಕಿನಲ್ಲಿ ಇಡಿ."
