                    "ಸಾಧ್ಯವಿದ್ದರೆ ಅಡುಗೆಮನೆ ದಕ್ಷಿಣ-ಪೂರ್ವಕ್ಕೆ ಸ್ಥಳಾಂತರಿಸಿ.",
                    "ದಕ್ಷಿಣ-ಪೂರ್ವದಲ್ಲಿ ಅಗ್ನಿ ತತ್ವದ ಚಿಹ್ನೆಗಳನ್ನು ಇಡಿ.",
