                    "ಸ್ಟೌವ್ ಅನ್ನು ದಕ್ಷಿಣ-ಪೂರ್ವ ವಿಭಾಗದಲ್ಲಿ ಇಡಿ.",
                    "ಪರಿಹಾರವಾಗಿ ಹಸಿರು ಅಥವಾ ಕಂದು ಬಣ್ಣ ಬಳಸಿ.",
                    "ಅಡುಗೆಮನೆಯ ಬಾಗಿಲನ್ನು ಸದಾ ಮುಚ್ಚಿರಲಿ.",
